// Wörtlich
public static double durchschnitt(int[] zahlen) {
    int summe = 0;
    for (int zahl : zahlen) {
        summe += zahl;
    }
    return (double) summe / zahlen.length;
}

// Idiomatisch mit Streams (Modul 11)
public static double durchschnitt(int[] zahlen) {
    return IntStream.of(zahlen).average().orElse(0);
}
